<script setup lang="ts">
import { computed,ref } from 'vue';
import { state,change,ui,tags } from '../state';
import { prepareActivityChange,suggestActivityCoverage,activityLabel } from '../domain/activity-planning';
import { activityForm,activityFromForm,activityText,type ActivityForm } from '../domain/activity-form';
import { clone } from '../services/application-state';
import { HOMEWORK_LOCATION,locationOptions } from '../domain/planning-locations';
import type { Activity } from '../domain/models';

const query=ref(''),tag=ref(''),selectedId=ref('');
const original=ref<Activity|null>(null),draft=ref<ActivityForm|null>(null);
const tagSearch=ref(''),customTag=ref(''),coverageSearch=ref(''),coverageStage=ref(''),selectedOnly=ref(false);
const allActivities=computed(()=>state.value!.progress.activities??[]);
const requirements=computed(()=>state.value!.requirements);
const activities=computed(()=>allActivities.value.filter(a=>{
 const words=[activityLabel(a),activityText(a.description),a.location,...(a.tags??[]),...a.covers.map(id=>requirements.value.find(r=>r.id===id)?.text??id)].join(' ').toLowerCase();
 return (!tag.value||a.tags?.includes(tag.value))&&words.includes(query.value.toLowerCase());
}));
const selected=computed(()=>activities.value.find(a=>a.id===selectedId.value)??activities.value[0]);
const tagOptions=computed(()=>[...new Set([...tags.value,...allActivities.value.flatMap(a=>a.tags??[]),...(draft.value?.tags??[])])].sort());
const visibleTags=computed(()=>tagOptions.value.filter(t=>t.toLowerCase().includes(tagSearch.value.toLowerCase())));
const locations=computed(()=>[...new Set(['Flexible / anywhere',HOMEWORK_LOCATION,...requirements.value.flatMap(locationOptions),...allActivities.value.map(a=>String(a.location??'')),draft.value?.location??''].filter(Boolean))]);
const coverageOptions=computed(()=>requirements.value.filter(r=>(!coverageStage.value||String(r.stage)===coverageStage.value)&&(!selectedOnly.value||draft.value?.covers.includes(r.id))&&`${r.text} ${r.stream} ${r.tags.join(' ')}`.toLowerCase().includes(coverageSearch.value.toLowerCase())));
const covered=computed(()=>requirements.value.filter(r=>selected.value?.covers.includes(r.id)));
const steps=computed(()=>activityText(selected.value?.instructions).split('\n').map(s=>s.replace(/^\s*(?:\d+[.)]|[-•])\s*/,'').trim()).filter(Boolean));
const duration=(a:Activity)=>Number(a.duration??a.duration_minutes)||60;
function glyph(a:Activity){const words=(a.tags??[]).join(' ').toLowerCase();return /navigation|compass|map/.test(words)?'⌖':/camp|shelter|tent/.test(words)?'△':/cook|food/.test(words)?'♨':'✦';}
function edit(a?:Activity){original.value=clone(a??{id:'activity-'+crypto.randomUUID(),title:'',description:'',duration:60,location:'Flexible / anywhere',tags:[],covers:[]});draft.value=activityForm(original.value);tagSearch.value='';coverageSearch.value='';coverageStage.value='';selectedOnly.value=false;customTag.value='';}
function save(){if(!draft.value||!original.value)return;try{const activity=activityFromForm(original.value,draft.value);if(change('Before activity edit',s=>{s.progress.activities=prepareActivityChange(s.progress.activities??[],activity,s.requirements);})){selectedId.value=activity.id;query.value='';tag.value='';draft.value=null;}}catch(e){ui.error=String(e);}}
function addTag(){const value=customTag.value.trim();if(value&&draft.value&&!draft.value.tags.includes(value))draft.value.tags.push(value);customTag.value='';}
function suggest(){if(!draft.value)return;draft.value.covers=suggestActivityCoverage(requirements.value,draft.value.tags,draft.value.location,draft.value.covers);ui.notice='Suggested coverage selected. Review the requirements before saving.';}
function remove(a:Activity){if(change('Before deleting activity',s=>{s.progress.activities=s.progress.activities?.filter(x=>x.id!==a.id);})){selectedId.value='';}}
</script>
<template>
 <section class="activity-studio-layout">
  <aside class="activity-bank"><div class="activity-bank-heading"><div><p class="eyebrow">REUSABLE SESSION IDEAS</p><h2>Activity Bank <span>{{allActivities.length}}</span></h2></div><button class="activity-create" :disabled="!!draft" @click="edit()">＋ Create activity</button></div>
   <div class="activity-bank-filters"><label>Search activities<input v-model="query" type="search" placeholder="Name, theme or skill"></label><label>Theme / tag<select v-model="tag" aria-label="Activity bank tag"><option value="">All themes and tags</option><option v-for="t in tagOptions" :key="t">{{t}}</option></select></label></div>
   <div class="activity-bank-list"><button v-for="a in activities" :key="a.id" :class="['activity-bank-card',{active:selected?.id===a.id}]" :aria-pressed="selected?.id===a.id" :disabled="!!draft" @click="selectedId=a.id"><span class="activity-card-symbol" aria-hidden="true">{{glyph(a)}}</span><span class="activity-card-content"><strong>{{activityLabel(a)}}</strong><span class="activity-card-description">{{activityText(a.description)||'Add a description to this activity.'}}</span><span class="activity-card-meta">{{duration(a)}} min · {{a.covers.length}} linked skills</span><span class="activity-card-location">{{a.location||'Flexible / anywhere'}}</span><span class="activity-card-tags"><span v-for="t in a.tags?.slice(0,2)" :key="t">{{t}}</span></span></span></button><div v-if="!activities.length" class="activity-bank-empty"><span aria-hidden="true">✦</span><h3>{{allActivities.length?'No matching activities':'Start your activity bank'}}</h3><p>{{allActivities.length?'Try another search or theme.':'Create an activity or import a bank through Data and State → Importer.'}}</p></div></div>
  </aside>
  <div class="activity-main">
   <form v-if="draft" class="activity-form" @submit.prevent="save"><div class="activity-editor-heading"><div><p class="eyebrow">ACTIVITY STUDIO</p><h2>{{allActivities.some(a=>a.id===original?.id)?'Edit activity':'Create activity'}}</h2></div><button type="button" @click="draft=null">Cancel</button></div>
    <section class="activity-form-section"><h3>The activity</h3><label>Activity name<input v-model="draft.title" required placeholder="e.g. Map and compass challenge"></label><label>Description<textarea v-model="draft.description" rows="3" placeholder="What will the Scouts do?" /></label><div class="activity-form-row"><label>Duration (minutes)<input v-model.number="draft.duration" type="number" min="1" max="1440" required></label><label>Location<select v-model="draft.location" aria-label="Activity location"><option v-for="location in locations" :key="location">{{location}}</option></select></label></div></section>
    <section class="activity-form-section"><h3>Themes and tags</h3><p>Help this activity match your weekly plans and OAS skills.</p><label>Find activity tags<input v-model="tagSearch" type="search" placeholder="Search available themes"></label><div class="activity-tag-options"><label v-for="t in visibleTags" :key="t" class="check"><input v-model="draft.tags" type="checkbox" :value="t">{{t}}</label><p v-if="!visibleTags.length">No matching tags. Add your own below.</p></div><div class="activity-custom-tag"><label>New tag<input v-model="customTag" placeholder="Add your own tag" @keydown.enter.prevent="addTag"></label><button type="button" @click="addTag">Add tag</button></div></section>
    <section class="activity-form-section"><h3>Running the activity</h3><label>Equipment<textarea v-model="draft.equipment" rows="3" placeholder="Equipment and materials to bring" /></label><label>Preparation<textarea v-model="draft.preparation" rows="3" placeholder="Set-up before the session" /></label><label>Instructions<textarea v-model="draft.instructions" rows="6" placeholder="Write each step on a new line" /></label></section>
    <section class="activity-form-section"><div class="activity-coverage-heading"><h3>OAS coverage <span>{{draft.covers.length}} selected</span></h3><button type="button" @click="suggest">Suggest coverage from tags and location</button></div><p>Review the suggested skills and tick the ones this activity covers. Coverage is a plan, not completion evidence.</p><div class="activity-coverage-filters"><label>Find OAS statements<input v-model="coverageSearch" type="search" placeholder="Search skill wording"></label><label>Stage<select v-model="coverageStage" aria-label="Activity coverage stage"><option value="">All stages</option><option v-for="n in [1,2,3]" :key="n">{{n}}</option></select></label><label class="check"><input v-model="selectedOnly" type="checkbox">Selected only</label></div><div class="activity-coverage-options"><label v-for="r in coverageOptions" :key="r.id" class="activity-coverage-option"><input v-model="draft.covers" type="checkbox" :value="r.id"><span>{{r.text}}<small>Stage {{r.stage}} · {{r.stream}}</small></span></label><p v-if="!coverageOptions.length">No statements match these filters.</p></div></section>
    <div class="activity-form-actions"><button type="submit" class="activity-save">Save activity</button><button type="button" @click="draft=null">Cancel</button></div>
   </form>
   <article v-else-if="selected" class="activity-reader"><div class="activity-reader-hero"><div class="activity-reader-symbol" aria-hidden="true">{{glyph(selected)}}</div><p class="eyebrow">ACTIVITY PLAN</p><h2>{{activityLabel(selected)}}</h2><p v-if="selected.description" class="activity-intro">{{activityText(selected.description)}}</p><div class="activity-reader-facts"><span><b>{{duration(selected)}}</b> minutes</span><span>{{selected.location||'Flexible / anywhere'}}</span><span><b>{{selected.covers.length}}</b> linked OAS skills</span></div><div v-if="selected.tags?.length" class="theme-chips"><span v-for="t in selected.tags" :key="t">{{t}}</span></div></div>
    <div class="activity-reader-toolbar"><button @click="edit(selected)">Edit activity</button><button class="activity-delete" @click="remove(selected)">Delete activity</button></div>
    <div class="activity-reader-body"><div class="activity-run-details"><section v-if="activityText(selected.equipment)"><h3>Equipment</h3><p class="activity-prose">{{activityText(selected.equipment)}}</p></section><section v-if="activityText(selected.preparation)"><h3>Preparation</h3><p class="activity-prose">{{activityText(selected.preparation)}}</p></section></div><section v-if="steps.length" class="activity-steps"><h3>How to run it</h3><ol><li v-for="(step,i) in steps" :key="i">{{step}}</li></ol></section><section class="activity-linked-skills"><h3>OAS coverage <span>{{selected.covers.length}} skills</span></h3><p>Linked skills are opportunities to practise. Scout completion is recorded separately.</p><div v-for="stage in [1,2,3]" :key="stage"><template v-if="covered.some(r=>r.stage===stage)"><h4>Stage {{stage}}</h4><button v-for="r in covered.filter(r=>r.stage===stage)" :key="r.id" class="activity-covered-skill" @click="ui.requirementId=r.id"><span>{{r.text}}</span><small>{{r.stream}} ↗</small></button></template></div><p v-if="!covered.length">No OAS skills linked yet. Edit this activity to add coverage.</p></section></div>
   </article><div v-else class="activity-reader-empty"><span aria-hidden="true">✦</span><h2>Your next Scout-night idea starts here</h2><p>Create a reusable activity with equipment, instructions and the OAS skills it supports.</p><button @click="edit()">Create activity</button></div>
  </div>
 </section>
</template>
